'AC-testing.benchmarks.13 AC-testing.benchmarks.14'; from __future__ import annotations; import argparse; import copy; import json; import re; from decimal import Decimal; from pathlib import Path; from typing import Any; from unittest.mock import MagicMock; from common.testing.benchmarks import generate_benchmark_index; from common.testing.benchmarks.benchmark_html_reporter import extract_summary_data, generate_html_report, generate_index_dashboard; from common.testing.benchmarks.cases.case_6 import execute_case_6; from common.testing.benchmarks.run_financial_scenario_benchmark import _save_reports; _case = lambda case_id, status='PASS', **details: {'case_id': case_id, 'case_name': case_id, 'status': status, 'duration_seconds': 1.0, 'details': details}
def _report(results: list[dict[str, Any]]) -> dict[str, Any]: results = copy.deepcopy(list(results)); passed = sum((r.get('status') == 'PASS' for r in results)); skipped = sum((r.get('status') == 'SKIPPED' for r in results)); failed = len(results) - passed - skipped; return {'version_ref': 'v-test', 'run_at': '2026-10-10T00:00:00+00:00', 'app_url': 'https://staging.example.test', 'summary': {'total': len(results), 'passed': passed, 'skipped': skipped, 'failed': failed, 'success': failed == 0 and skipped == 0}, 'results': results}
def _invariant_rows(page: str) -> dict[str, tuple[str, str]]: table = page.split('<table class="invariants-table">')[1].split('</table>')[0]; rows = re.findall('<tr>\\s*<td><strong>(.*?)</strong></td>\\s*<td><code>.*?</code></td>\\s*<td>(.*?)</td>\\s*<td><span class="badge badge-(?:pass|fail|skip)">(.*?)</span></td>\\s*</tr>', table, flags=re.DOTALL); return {name: (observed, badge) for name, observed, badge in rows}
_invariant_cells = lambda page: {name: badge for name, (_, badge) in _invariant_rows(page).items()}
def _stat_value(page: str, label: str) -> str: match = re.search(f'<span class="stat-label">{re.escape(label)}</span>\\s*<span class="stat-value">(.*?)</span>', page, flags=re.DOTALL); assert match, f'no stat box labelled {label!r}'; return match.group(1).strip()
_run = lambda version, run_at, **overrides: {'version': version, 'run_at': run_at, 'status': 'PASS', 'cases_total': 7, 'cases_passed': 7, 'duration_seconds': 10.0, 'max_equation_delta': '0.00', **overrides}; FULL_RUN = [_case('case_1', m1_closing_balance='111.11', cumulative_net_income='22.22', equation_delta='0.00'), _case('case_2', equation_delta='0.00'), _case('case_3', card_spend_recorded='33.33', bank_repayment='44.44', net_income='-33.33', equation_delta='0.00'), _case('case_4', equation_delta_sgd='0.00', equation_delta_usd='0.00'), _case('case_5', equation_delta='0.00'), _case('case_6', equation_delta='0.00')]; INVARIANT_CASES = {'Balance Sheet Identity': {'case_1', 'case_4', 'case_6'}, 'Temporal Multi-Period Rollforward': {'case_1'}, 'Credit Card Liability Clearance (No Double Counting)': {'case_3'}, 'Retained Earnings Articulation': {'case_1'}}
def test_AC_testing_benchmarks_13_the_invariants_table_passes_only_for_cases_that_passed() -> None:
    page = generate_html_report(_report(FULL_RUN)); assert _invariant_cells(page) == {'Balance Sheet Identity': 'PASS', 'Temporal Multi-Period Rollforward': 'PASS', 'Credit Card Liability Clearance (No Double Counting)': 'PASS', 'Retained Earnings Articulation': 'PASS'}
    for failed in ('case_1', 'case_2', 'case_3', 'case_4', 'case_5', 'case_6'): run = [_case(c['case_id'], 'FAIL', **c['details']) if c['case_id'] == failed else c for c in FULL_RUN]; assert _invariant_cells(generate_html_report(_report(run))) == {name: 'FAIL' if failed in cases else 'PASS' for name, cases in INVARIANT_CASES.items()}, failed
    for absent in ('case_1', 'case_3', 'case_4', 'case_6'): run = [c for c in FULL_RUN if c['case_id'] != absent]; assert _invariant_cells(generate_html_report(_report(run))) == {name: 'NOT RUN' if absent in cases else 'PASS' for name, cases in INVARIANT_CASES.items()}, absent
def test_AC_testing_benchmarks_14_the_latest_pass_rate_is_computed_from_the_latest_run() -> None: runs = [_run('v1', '2026-09-01T00:00:00'), _run('v2', '2026-09-02T00:00:00', status='FAIL', cases_passed=5)]; dashboard = generate_index_dashboard(runs); assert _stat_value(dashboard, 'Latest Pass Rate') == '5/7 (71%)'; assert 'The latest run did not pass: 5 of 7 cases passed' in dashboard; assert 'reconciled' not in dashboard; assert '<span class="badge badge-fail">FAIL</span>' in dashboard; assert 'Latest Deployed Release: v2' in dashboard; _m1_runner = _mock_case6_runner(final_delta='12.50'); _m1_case_res = execute_case_6(_m1_runner); assert _m1_case_res.status == 'FAIL'; _m1_verdicts = _m1_case_res.details['assertion_verdicts']; assert _m1_verdicts['overdraft_cash'] == 'passed'; assert _m1_verdicts['ending_cash_balance'] == 'passed'; assert _m1_verdicts['capital_gain'] == 'passed'; assert _m1_verdicts['net_income'] == 'passed'; assert _m1_verdicts['total_assets'] == 'passed'; assert _m1_verdicts['total_equity'] == 'passed'; assert _m1_verdicts['equation_delta'] == 'failed'; _m1_partial_details = copy.deepcopy(_m1_case_res.details); _m1_partial_details.pop('total_equity', None); _m1_partial_details['assertion_verdicts']['total_equity'] = 'not_run'; _m1_report = _report([{'case_id': 'case_6', 'case_name': _m1_case_res.case_name, 'status': 'FAIL', 'duration_seconds': 1.2, 'details': _m1_partial_details, 'error_message': _m1_case_res.error_message}]); _m1_page = generate_html_report(_m1_report); _m1_rows = _case_rows(_m1_page, 'case_6'); assert _m1_rows['Overdraft Checkpoint Cash Balance'] == ('-$1500.00 SGD', '✅ Negative Balance Equation Validated'); assert _m1_rows['Realized Capital Gain from Art Disposal'] == ('+$2500.00 SGD', '✅ Capital Gain Recognized in P&amp;L'); assert _m1_rows['Final Period Net Income'] == ('$0.00 SGD', '✅ Expense Offset by Capital Gain'); assert _m1_rows['Final Period Total Assets'] == ('$11000.00 SGD', '✅ Ending Assets Reconciled'); assert _m1_rows['Final Period Total Equity'] == ('n/a', 'n/a'); _m1_delta_val, _m1_delta_verdict = _m1_rows['Balance Sheet Equation Delta']; assert _m1_delta_val == '$12.50 SGD'; assert '❌' in _m1_delta_verdict and '12.50 SGD' in _m1_delta_verdict; _m2_report = {'version_ref': 'v-skip-ok', 'run_at': '2026-10-20T08:00:00+00:00', 'app_url': 'https://staging.example.test', 'summary': {'total': 2, 'passed': 1, 'skipped': 1, 'failed': 0, 'success': True}, 'results': [_case('case_1', 'PASS', equation_delta='0.00'), _case('case_2', 'SKIPPED')]}; _m2_summary = extract_summary_data(_m2_report); assert _m2_summary['status'] == 'PASS'; assert _m2_summary['cases_skipped'] == 1; _m2_page = generate_html_report(_m2_report); assert '<span class="badge badge-pass">1 OF 2 SCENARIOS PASSED, 1 SKIPPED</span>' in _m2_page; _m2_dashboard = generate_index_dashboard([_m2_summary]); assert 'The latest run did not pass' not in _m2_dashboard; assert '1 of 2 cases passed (1 skipped)' in _m2_dashboard; assert '<span class="badge badge-pass">PASS</span>' in _m2_dashboard; _m3_dishonest_report = {'version_ref': 'v-dishonest', 'run_at': '2026-10-20T08:00:00+00:00', 'app_url': 'https://staging.example.test', 'summary': {'total': 6, 'passed': 6, 'skipped': 0, 'failed': 0, 'success': True}, 'results': [_case('case_1', 'PASS', equation_delta='0.00'), _case('case_2', 'FAIL', equation_delta='5.00')]}; _m3_summary = extract_summary_data(_m3_dishonest_report); assert _m3_summary['status'] == 'FAIL'; assert _m3_summary['cases_total'] == 2; assert _m3_summary['cases_passed'] == 1; assert _m3_summary['cases_failed'] == 1; _m3_page = generate_html_report(_m3_dishonest_report); assert 'ALL 6 SCENARIOS PASSED' not in _m3_page; assert 'SUMMARY COUNT MISMATCH' in _m3_page; assert _stat_value(_m3_page, 'Scenarios Passed') == '1 / 2'; _m4_report = _report([_case('case_1', 'PASS', equation_delta='12.50')]); _m4_summary = extract_summary_data(_m4_report); assert _m4_summary['status'] == 'FAIL'; assert _m4_summary['cases_passed'] == 0; assert _m4_summary['cases_failed'] == 1; assert _m4_summary['rollforward_balanced'] is False; _m4_page = generate_html_report(_m4_report); assert 'Balanced' not in _m4_page; assert 'ALL 1 SCENARIOS PASSED' not in _m4_page; _m4_rows = _case_rows(_m4_page, 'case_1'); _m4_delta_cell, _m4_delta_badge = _m4_rows['Balance Sheet Equation Delta (A - L - E)']; assert _m4_delta_cell == '$12.50 SGD'; assert 'badge-fail' in _m4_delta_badge and '12.50 SGD' in _m4_delta_badge; _m5_report = _report([_case('case_1', 'FAIL', total_assets='24200.00')]); _m5_page = generate_html_report(_m5_report); _m5_card = _case_card(_m5_page, 'case_1'); assert 'No figures recorded. The case stopped before it recorded any.' not in _m5_card; assert 'No assertion table figures recorded. Inspect Raw Adjudication Telemetry below.' in _m5_card; _m6_c1 = _case('case_1', 'PASS', equation_delta='0.00'); _m6_c2 = _case('case_2', 'PASS', equation_delta='0.00'); _m6_c2['duration_seconds'] = None; _m6_report = _report([_m6_c1, _m6_c2]); _m6_summary = extract_summary_data(_m6_report); assert _m6_summary['duration_seconds'] is None; _m6_page = generate_html_report(_m6_report); assert _stat_value(_m6_page, 'Total Duration') == 'n/a'; _m7_report = _report([_case('case_4', 'FAIL', sgd_closing_balance='100.00', equation_delta_sgd='12.50', equation_delta_usd='0.00'), _case('case_6', 'FAIL', overdraft_cash='-1500.00', equation_delta='12.50')]); _m7_page = generate_html_report(_m7_report); _m7_c4_rows = _case_rows(_m7_page, 'case_4'); assert _m7_c4_rows['SGD Balance Sheet Equation Delta'][0] == '$12.50 SGD'; assert '12.50 SGD' in _m7_c4_rows['SGD Balance Sheet Equation Delta'][1]; assert _m7_c4_rows['USD Balance Sheet Equation Delta'][0] == '$0.00 USD'; assert '0.00 USD' in _m7_c4_rows['USD Balance Sheet Equation Delta'][1]; _m7_c6_rows = _case_rows(_m7_page, 'case_6'); assert _m7_c6_rows['Balance Sheet Equation Delta'][0] == '$12.50 SGD'; assert '12.50 SGD' in _m7_c6_rows['Balance Sheet Equation Delta'][1]; _m8_huge_int = 10 ** 5000; assert '</html>' in generate_html_report(None); assert '</html>' in generate_html_report(['not-a-dict']); assert extract_summary_data(None)['status'] == 'UNKNOWN'; assert '</html>' in generate_index_dashboard(None); _m8_weird_case = {'case_id': 'case_1', 'case_name': 'Weird Telemetry', 'status': 'FAIL', 'duration_seconds': _m8_huge_int, 'details': {Decimal('1.23'): 'decimal-key', ('tuple', 'key'): _m8_huge_int, 'm1_closing_balance': _m8_huge_int}}; _m8_page = generate_html_report({'summary': {'success': False}, 'results': [_m8_weird_case]}); assert '</html>' in _m8_page; assert 'decimal-key' in _m8_page; _m9_report = _report([_case('case_1', 'SKIPPED')]); _m9_page = generate_html_report(_m9_report); _m9_card = _case_card(_m9_page, 'case_1'); assert '<span class="badge badge-skip">SKIPPED</span>' in _m9_card; _m9_empty_dashboard = generate_index_dashboard([]); assert '<span class="badge badge-skip">UNKNOWN</span>' in _m9_empty_dashboard; assert '<span class="badge badge-fail">UNKNOWN</span>' not in _m9_empty_dashboard; _m9_tz_dashboard = generate_index_dashboard([_run('v-tz', '2026-10-19T09:12:00+08:00', status='UNKNOWN')]); assert '2026-10-19 09:12:00+08:00' in _m9_tz_dashboard; assert '<span class="badge badge-skip">UNKNOWN</span>' in _m9_tz_dashboard
def _case_card(page: str, case_id: str) -> str: tag = f'<span class="case-tag">{case_id.upper()}</span>'; assert tag in page, f'no card for {case_id}'; return page.split(tag, 1)[1].split('<div class="card scenario-card">', 1)[0]
def _case_rows(page: str, case_id: str) -> dict[str, tuple[str, str]]: card = _case_card(page, case_id); body = card.split('<tbody>', 1)[1].split('</tbody>', 1)[0]; rows = re.findall('<tr><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td></tr>', body, flags=re.DOTALL); return {label: (value, verdict) for label, value, verdict in rows}
def _mock_case6_runner(final_delta: str='12.50') -> MagicMock: runner = MagicMock(); runner.create_ephemeral_client.return_value = (MagicMock(), 'c6@test.local', {}); runner.create_account.side_effect = [{'id': 'acc-chk', 'name': 'Checking'}, {'id': 'acc-exp', 'name': 'Expense'}, {'id': 'acc-eq', 'name': 'Equity'}, {'id': 'acc-art', 'name': 'Art'}, {'id': 'acc-cg', 'name': 'CapGain'}]; runner.get_balance_sheet.side_effect = [{'total_assets': '-1500.00', 'total_liabilities': '0.00', 'total_equity': '1000.00', 'net_income': '-2500.00', 'unrealized_fx_gain_loss': '0.00', 'cta_adjustment': '0.00', 'net_worth_adjustment_gain_loss': '0.00', 'equation_delta': '0.00', 'is_balanced': True}, {'total_assets': '11000.00', 'total_liabilities': '0.00', 'total_equity': '11000.00', 'net_income': '0.00', 'unrealized_fx_gain_loss': '0.00', 'cta_adjustment': '0.00', 'net_worth_adjustment_gain_loss': '0.00', 'equation_delta': final_delta, 'is_balanced': final_delta == '0.00'}]; runner.get_balance_sheet_diagnostics.return_value = {'is_balanced': final_delta == '0.00'}; return runner
def test_AC_testing_benchmarks_13_lone_surrogates_are_sanitized_without_truncating_files(tmp_path: Path) -> None: report = _report([_case('case_1', 'FAIL', m1_closing_balance='100.00', note='bad surrogate \ud800 tail')]); report['results'][0]['error_message'] = 'boom \ud800 end'; args = argparse.Namespace(json_report=tmp_path / 'report.json', baseline=None, output_html=tmp_path / 'v-surrogate' / 'report.html', output_summary=tmp_path / 'v-surrogate' / 'summary.json'); _save_reports(args, report); html_text = args.output_html.read_text(encoding='utf-8'); assert '</html>' in html_text; summary_obj = json.loads(args.output_summary.read_text(encoding='utf-8')); assert summary_obj['status'] == 'FAIL'; (tmp_path / 'v-surrogate' / 'summary.json').write_text('{"version": "v-surrogate\\ud800", "run_at": "2026-10-20T00:00:00+00:00", "status": "FAIL"}', encoding='utf-8'); rc = generate_benchmark_index.main(['--benchmarks-dir', str(tmp_path)]); assert rc == 0; index_text = (tmp_path / 'index.html').read_text(encoding='utf-8'); assert '</html>' in index_text
